export async function choose(pick: Picker) {
  let h
  try {
    h = await pick({ suggestedName: 'backup.json' })
  } catch {
    return // closed the picker
  }
  await keep(h).catch(() => {}) // if it cannot be kept, it still works until the page closes
}

