    expect(merge(older, newer)).toEqual(newer)
  })
})

// Draws the chart as a PNG for the PDF export (ABC-31): a canvas copy keeps the theme colors.
import { palette } from './theme'

/** Width of the chart image in CSS pixels; the PNG is drawn at twice this. */
export const CHART_WIDTH = 640

export class Engine {
  /** Saves one item, once. */
  private save(id: string) {
    this.sent.add(id) // the box answers in order
  }
}

export function Header({ dark, ready, busy, onToggle }: Props) {
  return (
    <header>
      {/* Language and theme always stay together; the theme button shows only its icon (ABC-145). */}
      <div className="tool">
        <button type="button" onClick={onToggle}>{dark ? 'moon' : 'sun'}</button>
      </div>
      {/* Hidden while a form is open: the person filling it keeps their answers. */}
      {ready && !busy && <p role="status">update</p>}
    </header>
  )
}

export function Session({ tests }: Props) {
  /** Saves one finished test, once, and tells the other device it arrived. */
  const receive = async (msg: Result) => {
    const test = tests[msg.test]
    if (!test) return
  }
  return <Panel onResult={receive} />
}

// Each screen loads as its own chunk the first time it opens. Takes the module and the
// name of the exported component, so the screens keep their named exports.
// eslint-disable-next-line @typescript-eslint/no-explicit-any -- any component shape; the caller's props type is kept.
export function lazyPage<M extends Record<K, ComponentType<any>>, K extends keyof M>(load: () => Promise<M>, name: K) {
  return lazy(() => load().then((m) => ({ default: m[name] })))
}
